//! Raw bindings to the Bun OS emulator host C ABI (`bun_emu_host.h`), generated by bindgen in
//! dynamic-loading mode: open one core plugin (`bun_emu_<core>.dll`, `bun_emu_<core>.so`)
//! with [`BunEmuHost::new`] or [`BunEmuHost::from_library`]. The safe API is the `bun-emu-host`
//! crate.
#![allow(non_camel_case_types, non_upper_case_globals, non_snake_case, clippy::all, unsafe_op_in_unsafe_fn)]

include!(concat!(env!("OUT_DIR"), "/bindings.rs"));

/// Directory of the plugins built by `packages/bun-emu-host/scripts/build.ts` in this checkout.
pub const DEFAULT_PLUGIN_DIR: &str = env!("BUN_EMU_HOST_DEFAULT_DIR");

/// File name of a core plugin on this platform: `bun_emu_melonds.dll`, `bun_emu_melonds.so`.
pub fn plugin_file_name(core: &str) -> String {
    format!("bun_emu_{core}{}", std::env::consts::DLL_SUFFIX)
}
